import os, glob, re

def load_grids():
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}

    # Try to find the session file
    sessions_path = os.path.join(d, '../../sessions')
    try:
        basename = os.path.basename(d)
        jsonl_path = os.path.join(sessions_path, basename + '.jsonl')
        if os.path.exists(jsonl_path):
            t = open(jsonl_path).read()
            G = {}
            for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
                k, h, w = m[1], int(m[2]), int(m[3])
                rows = []
                remainder = t[m.end():].split('\n')[:h]
                for r in remainder:
                    if r.strip():
                        rows.append([int(x) for x in r.split()])
                if k not in G and all(len(row) == w and all(str(int(x)) == str(x) for x in row) for row in rows):
                    G[k] = [[int(x) for x in row] for row in rows]
            return G
    except Exception as e:
        print(f"Error loading: {e}")
        return {}

