def solve_with_relative_placement(grid):
    """Find connected components, sort by priority, pack per-column with relative positioning"""
    h, w = len(grid), len(grid[0])

    # Find all connected components
    visited = [[False]*w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                cells = []
                queue = [(r, c)]
                color = grid[r][c]
                visited[r][c] = True

                while queue:
                    cr, cc = queue.pop(0)
                    cells.append((cr, cc))

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < h and 0 <= nc < w:
                            if grid[nr][nc] == color and not visited[nr][nc]:
                                visited[nr][nc] = True
                                queue.append((nr, nc))

                comp = {
                    'cells': sorted(cells),
                    'color': color,
                    'h': max(c[0] for c in cells) - min(c[0] for c in cells) + 1,
                    'w': max(c[1] for c in cells) - min(c[1] for c in cells) + 1,
                    'min_r': min(c[0] for c in cells),
                    'min_c': min(c[1] for c in cells),
                }
                components.append(comp)

    print("All components:")
    for i, c in enumerate(components):
        print(f"  [{i}] color={c['color']}, h={c['h']}, w={c['w']}, min_r={c['min_r']}")

    # Sort by (-h, -w, min_r, min_c)
    sorted_comps = sorted(components, key=lambda x: (-x['h'], -x['w'], x['min_r'], x['min_c']))

    # Build lookup: cell_position -> (component, orig_row)
    cell_map = {}
    for idx, comp in enumerate(sorted_comps):
        for orig_r, orig_c in comp['cells']:
            key = (orig_c, orig_r)  # (column, original_row)
            cell_map[key] = (idx, orig_r)  # (component_sort_index, orig_row)

    print("\nCell map (cell->component_idx,orig_row):")
    for k, v in cell_map.items():
        print(f"  Cell {k}: component {v[0]} at input row {v[1]}")

    result = [[0]*w for _ in range(h)]
    start_row = h - 4

    # Collect cells per column
    col_cells = [[] for _ in range(w)]
    for (col, orig_r), (comp_idx, _) in cell_map.items():
        col_cells[col].append((comp_idx, orig_r))

    # Sort each column's cells by (component_sort_index, original_row)
    for col in range(w):
        col_cells[col].sort(key=lambda x: (x[0], x[1]))

    # Place cells
    for col in range(w):
        for target_idx, (comp_idx, orig_r) in enumerate(col_cells[col]):
            tr = start_row + target_idx
            if tr >= 0 and tr < h - 1:
                result[tr][col] = grid[orig_r][col]  # Get the actual color from input

    return result

